def streamCopyFile(src: str) -> str:
    ffmpeg = getFFmpeg()
    if not ffmpeg:
        raise RuntimeError("[스트림복사] FFmpeg 경로를 찾을 수 없습니다.")

    if not os.path.isfile(src):
        raise FileNotFoundError(f"[스트림복사] 파일을 찾을 수 없습니다: {src}")

    dirname   = os.path.dirname(src)
    basename  = os.path.basename(src)
    dst       = os.path.join(dirname, f"fixed_{basename}")

    cmd = [
        ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
        "-i", src, "-c", "copy", "-map", "0", dst
    ]

    print(f"[스트림복사] 시작: {basename}")
    print(f"[스트림복사] CMD : {' '.join(cmd)}")
    t0 = time.time()

    completed = subprocess.run(cmd, capture_output=True, text=True)
    dt = time.time() - t0

    if completed.returncode != 0:
        err = (completed.stderr or completed.stdout or "").strip()
        print(f"[스트림복사] 실패: {basename} ({dt:.2f}s) → {err}")
        raise RuntimeError(f"ffmpeg failed: {err}")

    try:
        size = os.path.getsize(dst)
    except Exception:
        size = -1

    print(f"[스트림복사] 완료: {basename} → {os.path.basename(dst)} "
          f"({size if size>=0 else '?'} bytes, {dt:.2f}s)")
    return dst


def validateEntryName(name: str) -> str:
    """Accept one filename component, never a path on either supported OS."""
    if (
        not isinstance(name, str)
        or not name
        or name in {'.', '..'}
        or '/' in name
        or '\\' in name
        or ntpath.splitdrive(name)[0]
        or any(ord(ch) < 32 or ord(ch) == 127 for ch in name)
    ):
        raise ValueError('new_name must be a single filename')
    if os.name == 'nt':
        stem = name.split('.', 1)[0].rstrip(' ').upper()
        reserved = {'CON', 'PRN', 'AUX', 'NUL', 'CONIN$', 'CONOUT$'}
        reserved.update(f'{prefix}{i}' for prefix in ('COM', 'LPT') for i in range(1, 10))
        if ':' in name or name.endswith((' ', '.')) or stem in reserved:
            raise ValueError('new_name is not a regular Windows filename')
    return name


def childDestination(parent: str, name: str, allowedRoots: List[str] = None) -> str:
    dst = os.path.join(normPath(parent), validateEntryName(name))
    if allowedRoots is not None:
        # Includes existing symlinks at the destination, not just the parent.
        ensureInRoots(dst, allowedRoots)
    return dst


def renamePath(src: str, newName: str, allowedRoots: List[str] = None) -> str:
    dst = childDestination(os.path.dirname(src), newName, allowedRoots)
    os.replace(src, dst)
    return dst


def mkdirPath(parent: str, name: str, allowedRoots: List[str] = None) -> str:
    p = childDestination(parent, name, allowedRoots)
    os.makedirs(p, exist_ok=True)
    return p


# 녹화 중인 파일(풀 경로) 목록
def busyFilePaths(recorderManager, channels: List[dict]) -> List[str]:
    busy = []
    for c in channels:
        cid = c.get("id")
        if recorderManager.get_recording_status(cid):
            fn = recorderManager.get_recording_filename(cid)
            if fn:
                busy.append(normPath(fn))
    return busy


# 녹화중 파일 잠금
def isLocked(path: str, busyPaths: List[str]) -> bool:
    rp = normPath(path)
    for bp in busyPaths:
        if rp == bp:
            return True
        # 파일이 들어있는 폴더 자체를 옮기거나 지우는 것도 잠금
        if rp.startswith(os.path.dirname(bp) + os.sep):
            return True
    return False


def isPreviewable(path: str) -> bool:
    ext = os.path.splitext(path)[1].lower()
    return ext in {".mp4", ".webm", ".mkv", ".ts", ".m4v", ".mov", ".mp3", ".m4a", ".aac", ".wav", ".flac"}


def parseRangeHeader(rangeHeader: str, fileSize: int):
    try:
        if not rangeHeader or not rangeHeader.startswith("bytes="):
            return None
        rng = rangeHeader.split("=", 1)[1].strip()
        start_s, end_s = (rng.split("-", 1) + [""])[:2]
        if start_s == "":
            # bytes=-500  (끝에서 500바이트)
            length = int(end_s)
            if length <= 0: return None
            start = max(0, fileSize - length)
            end = fileSize - 1
        else:
            start = int(start_s)
            end = fileSize - 1 if end_s == "" else int(end_s)
            if start > end or start < 0: return None
        end = min(end, fileSize - 1)
        return (start, end)
    except Exception:
        return None

def guessMime(path: str) -> str:
    mime, _ = mimetypes.guess_type(path)
    return mime or "application/octet-stream"

