}

/* 버전 업데이트 내역 페이지 스타일 */
#version-history {
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: stretch;
      margin: 0 auto 24px;
      text-align: left;
      padding: 20px;
}

#version-history .patch-list,
#version-history .patch-sections,
#version-history .patch-details {
      list-style: none;
      margin: 0;
      padding: 0;
}

#version-history .patch-version {
      list-style: none;
      margin: 0;
      padding: 0;
}

#version-history .patch-version > strong {
      display: block;
      margin: 4px 0 12px;
      font-size: 1.02rem;
      color: var(--text);
}

#version-history .patch-subtitle {
      margin: 10px 0 14px;
      padding: 8px 12px;
      border: 1px solid var(--border);
      border-radius: 10px;
      background: var(--surface-muted);
      color: var(--text);
      font-weight: 800;
}

#version-history .patch-section {
      list-style: none;
      margin: 0;
      padding: 14px 0 14px;
      border-top: 1px dashed var(--border);
}

#version-history .patch-section:first-child {
      border-top: 0;
      padding-top: 4px;
}

#version-history .patch-topic {
      margin: 0 0 8px;
      color: var(--text);
      font-weight: 800;
      line-height: 1.55;
}

#version-history .patch-topic::before {
      content: "＊ ";
      color: var(--brand-ink);
      font-weight: 900;
}

#version-history .patch-details {
      padding-left: 20px;
}

#version-history .patch-details li {
      position: relative;
      margin: 5px 0;
      padding-left: 14px;
      color: var(--text-muted);
      line-height: 1.6;
}

#version-history .patch-details li::before {
      content: "-";
      position: absolute;
      left: 0;
      color: var(--text-muted);
}

@media (max-width: 768px) {
      #version-history {
            padding: 16px;
      }

      #version-history .patch-details {
            padding-left: 12px;
      }

      #version-history .patch-details li {
            padding-left: 12px;
            line-height: 1.55;
      }
}

