/* 인덱스 */
.page-index {

  /* 시스템 폰트 스택 + 기본 간격 */
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue",
                 Arial, "Noto Sans", "Apple SD Gothic Neo", "Malgun Gothic",
                 "맑은 고딕", "Segoe UI Emoji", "Segoe UI Symbol", sans-serif;
    line-height: 1.5;

}
.hero-index {
    text-align: center;
    margin: 8px auto 14px;

}
.hero-index h2 {
    font-size: 1.6rem;
    font-weight: 800;
    letter-spacing: .2px;
    margin: 0;

}
.chip {
    display: inline-block;
    padding: 4px 10px;
    border-radius: 999px;
    font-size: .8rem;
    line-height: 1;
    border: 1px solid rgba(0,0,0,.08);
    vertical-align: middle;

}
.chip--ver {
   margin-left: 6px;
   background: var(--accent);
   color: var(--brand-ink);

}
.chip--ok {
   background: #ecfdf5;
   color: #065f46;

}
.card {
    --surface: #fff;
    --border: rgba(0,0,0,.08);
    --shadow: 0 6px 16px -10px rgba(0,0,0,.25);

    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 14px;
    box-shadow: var(--shadow);

}
.compat-card {
    max-width: 860px;
    margin: 10px auto 20px;
    padding: 18px 20px;

}
.card-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding-bottom: 8px;
    border-bottom: 1px solid rgba(0,0,0,.06);

}
.card-head .eyebrow {
    font-size: .9rem;
    font-weight: 700;
    color: var(--text);

}
.kv-grid {

  /* 정의목록을 카드 안 전용 레이아웃으로 */
    margin: 10px 0 0;
    padding: 0;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px,1fr));
    gap: 10px 12px;

}
.kv {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 12px;
  background: var(--surface);
  border: 1px solid var(--border);
}
.kv dt {
  margin: 0;
  color: var(--text-muted);
  font-weight: 700;
}
.kv dd {
  margin: 0;
  font-family: ui-monospace, "SFMono-Regular", Menlo, Monaco,
               Consolas, "Liberation Mono", "Courier New", monospace;
  font-weight: 800;
  letter-spacing: .2px;
  padding: 2px 8px;
  border-radius: 8px;
  background: var(--surface-muted);
  border: 1px solid var(--border);
  color: var(--text);
}
.compat-note {
    margin: 12px 2px 2px;
    color: var(--text-muted);
    font-size: .92rem;

}

.spec-card {
    max-width: 860px;
    margin: 12px auto 18px;
    padding: 16px 18px;
}

/* 제목 */
.spec-card h3 {
    margin: 0 0 10px;
    font-size: 1.05rem;
    font-weight: 800;
    letter-spacing: .2px;
    color: var(--text);
}

/* 칩 배치 */
.spec-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin: 8px 0 6px;
}

/* 리스트(아이콘/이모지 포함 가독성 보강) */
.spec-list {
    list-style: none;
    padding: 0;
    margin: 8px 0 0;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px,1fr));
    gap: 6px 12px;
}

.spec-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 10px;
  color: var(--text);
}

.spec-list b {
  font-weight: 800;
  color: var(--text);
}

.changelog {
    list-style: none;
    margin: 10px 0 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 14px; /* 항목간 간격 */
}

.changelog li {
  font-size: .95rem;
  line-height: 1.6;
  color: var(--text-muted);
}

.changelog li b {
  display: block;
  margin-bottom: 4px;
  color: var(--text);
  font-weight: 800;
}

.changelog .sub {
  display: block;
  margin-left: 14px;
  font-size: .88rem;
  color: var(--text-muted);
}


/* 라이트 팔레트 (눈부심↓ / 연보라 포인트 유지) */
:root{
  --bg:#f5f6fb;
  --surface:#fbfcff; /* 큰 면적 눈부심 완화 */
  --card:#ffffff;
  --surface-muted:#f3f4f6;
  --border:#e3e7f2;
  --text:#0f172a;
  --text-muted:#64748b;

  /* 포인트(연보라) */
  --accent:#eef2ff;
  --accent-strong:#c7d2fe;
  --brand: var(--accent-strong);
  --brand-dark:#b7c3ff; /* hover용 */
  --brand-ink:#3730a3;

  /* 링크/포커스 */
  --link:#4f46e5;
  --link-hover:#3730a3;
  --focus-ring: rgba(99,102,241,.55);

  /* 버튼/아이콘 공통 */
  --btn-primary-bg: var(--brand);
  --btn-primary-hover: var(--brand-dark);
  --btn-text:#111827;
  --icon:var(--text);

  /* 네비게이션(상단바) */
  --nav-bg: var(--brand);
  --nav-text: var(--text);
  --nav-icon: var(--icon);

  /* 반투명(글래스) UI용 공통 변수 */
  --glass-bg: rgba(255,255,255,.92);
  --glass-hover: rgba(17,24,39,.06);
  --glass-active: rgba(17,24,39,.12);

  /* 브라우저 기본 UI(폼·스크롤)도 라이트/다크 지원 */
  color-scheme: light dark;
}

/* 다크 팔레트 */
@media (prefers-color-scheme: dark) {

	:root{
  --bg:#0b0f14;
  --surface:#0f1520;
  --card:#0f1520;
  --surface-muted:#111827;
  --border:rgba(255,255,255,.14);
  --text:#e6ebf2;
  --text-muted:#a8b3c2;

  --accent:#1b2233;
  --accent-strong:#9fb0ff;
  --brand:#c7d2fe;
  --brand-dark:#9fb0ff;
  --brand-ink:#c7d2fe;

  --link:#9fb0ff;
  --link-hover:#c7d2fe;
  --focus-ring: rgba(159,176,255,.75);

  --btn-primary-bg:#1b2233;
  --btn-primary-hover:#24314a;
  --btn-text:#e6ebf2;
  --icon:var(--text);

  /* 네비게이션(상단바) */
  --nav-bg: var(--surface);
  --nav-text: var(--brand);
  --nav-icon: var(--brand);

  /* 반투명(글래스) UI용 공통 변수 */
  --glass-bg: rgba(15,21,32,.92);
  --glass-hover: rgba(255,255,255,.06);
  --glass-active: rgba(255,255,255,.12);

  color-scheme: dark;
}

/* 다크 모드에서 모바일 액션바/하이라이트 눈부심 방지 */
@media (max-width: 900px) {
  .mobile-actionbar{
    background: rgba(15,21,32,.92);
    border-top: 1px solid var(--border);
  }
  .mobile-actionbar button:not(:disabled):hover{ background: rgba(255,255,255,.08); }
  .mobile-actionbar button:not(:disabled):active{ background: rgba(255,255,255,.12); }
}

	/* 카드/컨테이너: 배경 한 톤 어둡게, 테두리 대비↑ */
	.card {
			--surface: #0f1520;
			--border: rgba(255,255,255,.14);
			--shadow: 0 8px 20px -12px rgba(0,0,0,.8);
	}
	.card-head { border-bottom-color: rgba(255,255,255,.14); }

	/* 사용된 프로그램/버전 K/V 카드: 가독성↑(흰색 눈부심↓) */
	.kv {
			background: #0f1520;               /* 투명도 배경 → 실색 배경 */
			border-color: rgba(255,255,255,.16);
	}
	.kv dt {
			color: #d7deea;                    /* 순백에 가까운 톤 ↓ */
	}
	.kv dd {
			background: #0e1624;               /* 내용부는 조금 더 어둡게 */
			color: #dde5ef;                    /* 본문 가독성↑ */
			border-color: rgba(255,255,255,.18);
	}

	/* 안내 문구(호환/주의 등): 너무 흐리지 않도록 살짝 상향 */
	.compat-note {
			color: var(--text-muted);
	}

	/* 섹션 제목(권장사양 등): 본문 대비 보다 한 단계 밝게 */
	.spec-card h3 { 
			color: var(--text);
	}

	/* 권장사양 리스트: 배경 고정색 + 텍스트/테두리 대비↑ */
	.spec-list li {
			border-color: rgba(255,255,255,.16);
			background: #111a29;               /* 투명 배경 → 실색 배경 */
			color: #dde5ef;                    /* 본문 가독성↑ */
	}
	.spec-list b { 
			color: #ffffff;                    /* 강조는 선명하게 */
	}
	.spec-card{
			background:#0f1520;                   /* 섹션 카드 배경 고정 */
			border-color:rgba(255,255,255,.16);   /* 테두리 대비 ↑ */
	}

	/* 상단 칩/배지(“CPU ≥ 4스레드”, “RAM ≥ 4GB” 등) */
	.spec-card .chip,
	.spec-card .badge{
			color:#374151;                        /* 보라 톤 텍스트 */
			border-color:#1b2233;
	}

	/* OK/성공류 칩이 있다면 */
	.spec-card .chip--ok,
	.spec-card .badge--ok{
			background:#0f291e;
			color:#7ce1a4;
	}

	/* 리스트(아이콘+텍스트 줄) — 범위를 섹션 내부로 좁혀 우선순위 ↑ */
	.spec-card .spec-list li{
			background:#111a29;
			border-color:rgba(255,255,255,.16);
			color:#dde5ef;
	}
	.spec-card .spec-list b{ color:#ffffff; }

	/* 아이콘 색상 */
	.spec-card .spec-list .ico{
			color:#9fb0ff; fill:#9fb0ff;
	}

	/* 보조설명 */
	.spec-card .muted,
	.spec-card .compat-note{ color: var(--text-muted) }

	/* 테이블/폼 다크모드 가독성 보강 */
	.common-table {
			background: var(--surface);
			border-color: var(--border);
			color: var(--text);
	}
	.common-table thead th {
			background: var(--accent);
			color: var(--text);
			border-bottom-color: var(--border);
	}
	.common-table tbody td {
			color: var(--text);
			border-top-color: rgba(255,255,255,.08); 
	}
	.common-table tbody tr:hover {
			background: rgba(255,255,255,.04);
	}

	/* 칩/뱃지 테두리 대비 보강 */
	.chip { border-color: rgba(255,255,255,.16); 
	}

}


