/* 스크롤바 스타일링 */
.popup-logmessage::-webkit-scrollbar {
    width: 8px;

}

.popup-logmessage::-webkit-scrollbar-thumb { 
	background: var(--accent-strong); 
}

.popup-logmessage::-webkit-scrollbar-thumb:hover { 
	filter: brightness(.95); 
}

.popup-logmessage::-webkit-scrollbar-track { 
	background: var(--accent); 
}


/* 토글 스위치 스타일 */
.switch {
    position: relative;
    display: inline-block;
    width: 50px;
    height: 28px;

}
.toggle-top-left {
    position: absolute;
    top: 10px;
    left: 10px;
    z-index: 2;

}
.switch input {
    opacity: 0;
    width: 0;
    height: 0;
    position: absolute;
    cursor: pointer;

}
.slider {
    position: absolute;
    cursor: pointer;
    top: 0;
   left: 0;
   right: 0;
   bottom: 0;
    background-color: #ccc;
    transition: .4s;
    border-radius: 34px;

}
.slider:before {
    content: "";
    position: absolute;
    height: 22px;
    width: 22px;
    left: 3px;
    bottom: 3px;
    background-color: #fff;
    transition: .4s;
    border-radius: 50%;

}
.switch input:checked + .slider {
    background-color: var(--nav-bg);

}
.switch input:checked + .slider:before {
    transform: translateX(22px);


}

/* 채널이 OFF 상태일 때 */
.channel-disabled {
		filter: grayscale(100%);
		opacity: 0.6;

}

/* 같이보기 뱃지 */
.watchparty-badge {
    position: absolute;
    bottom: 10px;
    right: 5px;
    background-color: rgba(0, 0, 0, 0.6);
    color: #fff;
    padding: 2px 4px;
    font-size: 14px;
    border-radius: 3px;

}

/* 설정 페이지 스타일 */
.page-config {
