/* 파일관리 페이지 */

/* 파일관리 비활성 시, 본문 래퍼 숨김 (서버렌더 즉시 적용) */
body[data-fm-enabled="0"] #files-app {

    display: none !important;


}
.modal {
    position: fixed;
   inset: 0;
    display: flex;
   align-items: center;
   justify-content: center;
    background: rgba(0,0,0,.45);
    z-index: 9999;

}
.modal.hidden {
   display: none;


}
.modal .modal-content {
  position: relative;
  background: var(--card);
  color: var(--text);
  border: 1px solid var(--border);
  width: 480px;
  max-width: 90vw;
  padding: 16px;
  border-radius: 12px;
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
}
.modal .modal-content h3 {
    margin: 0 0 10px 0;
    font-size: 18px;

}
.modal .modal-content p,
.modal .modal-content ol {
   margin: 8px 0;

}
.modal .modal-content code {
    background: var(--surface-muted);
    padding: 2px 6px;
    border-radius: 6px;

}

/* 버튼 영역 */
.modal .button-row {
    display: flex;
    gap: 8px;
    justify-content: flex-end;
    margin-top: 16px;

}
.modal .button-row button {
    padding: 8px 14px;
    border-radius: 8px;
    border: 1px solid transparent;
    cursor: pointer;
    font-weight: 600;

}

/* 기본버튼: 설정으로 이동 */
.modal .button-row #go-config {
    background: var(--btn-primary-bg);
    color: var(--btn-text);
    border: 1px solid var(--border);
}
.modal .button-row #go-config:hover { background: var(--btn-primary-hover); }


/* 보조버튼: 닫기 */
.modal .button-row .secondary {
  background: var(--surface-muted);
  color: var(--text);
  border-color: var(--border);
}
.modal .button-row .secondary:hover { background: var(--accent); }

/* 사이드내브보다 위로 */
.modal {
    z-index: 2000;

}

/* 설명(텍스트) 공통 스타일 */
p.description{
