/* 모바일 반응형 */

/* 녹화현황 페이지 모바일 */
@media (max-width: 768px) {

  /* 1) 채널 목록은 그리드 자동 맞춤, 좁은 화면에서 줄바꿈 */
  .page-recording #channel-list{
    display: grid;                                  
    grid-template-columns: 1fr;                  
    gap: 12px;                                     
    justify-items: center;
    width: 100%;
    overflow-x: hidden;
  }

  /* 2) 카드는 폭 유동 + 공통 라운딩/패딩 유지 */
  .page-recording .channel{
    width: 100%;
    max-width: 420px;                               
    padding: 14px 12px 16px;
    box-sizing: border-box;
    border-radius: 12px;                        
  }

  /* 썸네일 컨테이너 */
  .page-recording .channel-thumbnail-container{
    margin-bottom: 12px;
    border-radius: 12px;
    overflow: hidden;
  }

  /* 썸네일: 16:9 + cover로 높이 균일 */
  .page-recording .channel-thumbnail{
    display: block;
    width: 100%;
    aspect-ratio: 16 / 9;                        
    object-fit: cover;                             
    height: auto;
    border-radius: 12px;
    margin-bottom: 0;
  }

  /* 텍스트 정렬 */
  .page-recording .channel-info{ text-align: center; }

  /* 버튼은 모바일에서는 가로 가득 + 터치 영역 확보 */
  .page-recording .channel button{
    width: 100%;
    max-width: none;                                
    padding: 12px 14px;                       
  }

  /* 필터 영역은 1열 그리드로 스택, 모든 컨트롤 100% */
  .filter-container{
    display: grid;                                  
    grid-template-columns: 1fr;
    gap: 10px;
    width: 100%;
    max-width: 600px;
    margin: 16px auto;
    padding: 10px;
  }
  .filter-container div{
    display: grid;                                 
    grid-template-columns: 1fr;
    gap: 6px;
    width: 100%;
    margin-bottom: 0;
  }
  .filter-container label{
    font-weight: 700;
    margin: 0;                              
  }
  .filter-container select,
  .filter-container input{
    width: 100% !important;
    margin: 0 !important;
    padding: 10px;
    font-size: 16px;
    border: 1px solid var(--border);
    border-radius: 8px;
    box-sizing: border-box;
    background: var(--surface);
    color: var(--text);
  }

  /* 6) 로그 팝업은 모바일에서 숨김 유지 */
  .popup-logmessage{ display: none !important; }
}


