/* 파일관리 페이지 */

/* 레이아웃 기본값 */
.page-files *,
.page-files *::before,
.page-files *::after {
    box-sizing: border-box;
}

body.page-files {
    background: var(--bg); 
}

/* 컨텐츠 최대폭 */
.page-files #content {
		max-width: 1200px;
		margin: 0 auto;
}

/* 툴바 */
.file-toolbar {
		background: var(--card); 
		border: 1px solid var(--border);
		border-radius: 12px;
		padding: 12px;
		box-shadow: 0 6px 16px -12px rgba(0,0,0,.25);
		display: grid;
		gap: 10px;
		margin: 12px 0 16px;
}

.file-toolbar .toolbar-row {
		display: flex;
		gap: 10px;
		align-items: center;
		flex-wrap: wrap;
}

.file-toolbar label {
		color: var(--text-muted);
		font-weight: 700;
}

.file-toolbar input[type="text"],
.file-toolbar select {
		border: 1px solid var(--border);
		border-radius: 10px;
		padding: 10px 12px;
		background: var(--surface);
		min-width: 12ch;
}

.file-toolbar button {
		border: 1px solid var(--border);
		background: var(--surface);
		color: #111827;
		padding: 10px 12px;
		border-radius: 10px;
		font-weight: 700;
		cursor: pointer;
}

.file-toolbar button:hover {
		background: var(--brand-dark);
		border-color: #d9e2f2;
}

#btnRefresh {
		color: var(--link);
		border-color: #cfe0ff;
}

/* 보기 토글(숨김 항목 표시) 라벨 */
.toggle-inline {
		display: inline-flex;
		align-items: center;
		gap: 6px;
		color: #374151;
		cursor: pointer;
		user-select: none;
}

.toggle-inline input {
		width: 16px;
		height: 16px;
}

/* 브레드크럼  */
.breadcrumbs {
		display: flex;
		flex-wrap: wrap;
		gap: 8px;
		align-items: center;
		margin: 8px 0 12px;
}

.breadcrumbs a {
		display: inline-flex;
		align-items: center;
		gap: 8px;
		text-decoration: none;
		background: var(--accent);
		color: var(--brand-ink);
		border: 1px solid var(--accent-strong);
		padding: 6px 10px;
		border-radius: 999px;
		font-weight: 700;
}

.breadcrumbs a:hover {
    background: var(--accent);
}

/* 디스크 요약 */
#storage-summary {
		display: flex;
		flex-wrap: wrap;
		gap: 8px;
		margin-bottom: 8px;
}

.disk-chip {
		display: inline-flex;
		align-items: center;
		gap: 8px;
		padding: 6px 10px;
		border: 1px solid var(--border);
		border-radius: 999px;
		background: var(--surface);
		box-shadow: 0 6px 16px -12px rgba(0,0,0,.25);
		font-size: .92rem;
}

.disk-chip .bar {
		width: 96px;
		height: 8px;
		background: var(--surface-muted);
		border-radius: 999px;
		overflow: hidden;
}

.disk-chip .bar > i {
		display: block;
		height: 100%;
		background-color: var(--nav-bg);
		width: 0%;
}

/* 파일 목록 (리스트 뷰) */
.file-list {
		display: flex;
		flex-direction: column;
		gap: 10px;
}

.file-item {
		background: var(--card); 
		border: 1px solid var(--border);
		border-radius: 12px;
		padding: 12px;
		display: flex;
		align-items: flex-start;
		justify-content: space-between;
		gap: 12px;
		box-shadow: 0 6px 16px -12px rgba(0,0,0,.25);
}

.file-item .fi-left {
		display: flex;
	  align-items: center;
		gap: 12px;
		min-width: 0;
}

.fi-icon {
		width: 36px;
		height: 36px;
		border-radius: 8px;
		display: flex;
		align-items: center;
		justify-content: center;
		background: #f5f6fb;
		border: 1px solid #e6e8f2;
		font-size: 18px;
		flex: 0 0 auto;
}

.fi-icon.file   { background: var(--surface-muted); }
.fi-icon.folder { background: #fff7ed; }

.fi-main {
		min-width: 0;
		display: flex;
		flex-direction: column;
		gap: 2px;
}

.fi-name {
		font-weight: 700;
		color: #111827;
		max-width: 64vw;
		white-space: nowrap;
		overflow: hidden;
		text-overflow: ellipsis;
		cursor: pointer; /* 폴더/파일 오픈 */
}

.fi-type {
		font-size: .85rem;
		color: var(--text-muted);
}

/* 2×2 작업 버튼 */
.file-item .fi-actions {
		display: grid;
		grid-template-columns: repeat(2, minmax(0, 1fr));
		gap: 8px;
		width: 220px;
		flex: 0 0 auto;
}

.file-item .fi-actions button {
		border: 1px solid var(--border);
		background: var(--surface);
		border-radius: 8px;
		padding: 8px 10px;
		font-weight: 700;
		cursor: pointer;
}

.file-item .fi-actions button:hover {
		background: var(--brand-dark);
		border-color: #d9e2f2;
}

/* 숨김 항목 표시/비표시 지원 */

.is-hidden { display: none !important; }
body.show-hidden .is-hidden { display: flex !important; }

.modal {
		position: fixed;
		inset: 0;
		display: none; /* 기본은 숨김 */
		align-items: center;
		justify-content: center;
		background: rgba(0,0,0,.45);
		z-index: 2000;
}

.modal.hidden {
		display: none;
}

.modal .modal-content {
  position: relative;
  background: var(--card);
  color: var(--text);
  border: 1px solid var(--border);
  width: 480px;
  max-width: 90vw;
  padding: 16px;
  border-radius: 12px;
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
}

.modal .modal-content h3 {
		margin: 0 0 10px;
		font-size: 18px;
}

.modal .modal-content p,
.modal .modal-content ol {
	 margin: 8px 0;
}

.modal .button-row {
		display: flex;
		gap: 8px;
		justify-content: flex-end;
		margin-top: 16px;
}

.modal .button-row button {
		padding: 8px 14px;
		border-radius: 8px;
		border: 1px solid transparent;
		font-weight: 700;
		cursor: pointer;
}

.modal #go-config {
		background-color: var(--nav-bg);
		color: #ffffff;
}

.modal #go-config:hover {
	 filter: brightness(.95);
}

.modal .secondary {
		background: #f2f2f2;
		color: #333333;
		border-color: #dddddd;
}

.modal .secondary:hover {
	  background: var(--brand-dark);
}

/* 파일매니저 비활성 시 자동 표시 */
body[data-fm-enabled="0"] #files-app {
		display: none !important;
}

body[data-fm-enabled="0"] #fm-disabled-modal {
		display: flex !important;
}

/* 테이블(데스크탑 리스트) 기본 스타일 */
.table-wrap { overflow: auto; }

/* 테이블 가독성 & 말줄임 + 고정 레이아웃 */
.table-wrap .common-table { 
		table-layout: fixed; 
		width: 100%; 
}

.common-table {
		width: 100%;
		border-collapse: separate;
		border-spacing: 0;
		background: var(--surface);
		border: 1px solid var(--border);
		border-radius: 12px;
		box-shadow: 0 6px 16px -12px rgba(0,0,0,.25);
}

/* 헤더: 중앙정렬(이름만 좌측 유지) */
.common-table thead th {
		position: sticky; top: 0;
		background: var(--surface-muted);
		color: #374151;
		font-weight: 700;
		padding: 10px 12px;
		border-bottom: 1px solid var(--border);
		text-align: center;
}

.common-table thead th.col-name { text-align: left; }

.common-table tbody td {
		padding: 10px 12px;
		border-top: 1px solid var(--border);
		vertical-align: middle;
}
.common-table tbody tr:hover { background: var(--accent); }

/* 컬럼 폭/정렬(버튼 영역 확보가 우선) */
.common-table thead th.col-type,
.common-table tbody td.col-type { width: 8ch; text-align: center; }

.common-table thead th.col-name,
.common-table tbody td.col-name { width: auto; }

.common-table thead th.col-size,
.common-table tbody td.col-size { width: 9ch; text-align: center; }

.common-table thead th.col-mtime,
.common-table tbody td.col-mtime { width: 18ch; text-align: center; }

/* 1×4 버튼 가로 배치 + 충분한 가로폭 확보 */
.common-table thead th.actions,
.common-table tbody td.actions { 
		width: 340px; 
		text-align: center; 
		white-space: nowrap;
}
.common-table tbody td.actions button { 
		display: inline-block; 
		margin-right: 6px; 
}

/* 이름 버튼(말줄임) */
.linklike {
		background: none; 
		border: 0; 
		padding: 0;
		color: var(--link); 
		font-weight: 700; 
		cursor: pointer;
		text-align: left;
}
.table-wrap .common-table td.col-name .linklike {
		display: inline-block; 
		max-width: 100%; 
		overflow: hidden; 
		text-overflow: ellipsis; 
		white-space: nowrap; 
}

/* 덜 중요한 수치들 살짝 약하게 */
.table-wrap .common-table td.col-size,
.table-wrap .common-table td.col-mtime {
		font-size: .9rem; 
		color: var(--text-muted); 
}

/* 전역 hidden 유틸 */
.hidden { display: none !important; }

/* 모달: 기본은 보이게, hidden 때만 숨김 */
.modal {
		position: fixed;
		inset: 0;
		display: flex;         
		align-items: center;
		justify-content: center;
		z-index: 9999;
}
.modal.hidden { display: none !important; }

@media (min-width: 901px){ #mobileActionBar{ display:none; } }

/* 모바일(리스트) */
@media (max-width: 900px) {
  /* 데스크탑 테이블 숨김, 모바일 리스트만 사용 */
  #tableViewWrap { display: none; }
  #fileListMobile.grid-view { 
    display: grid; 
    grid-template-columns: 1fr !important;
    gap: 10px; 
    overflow-x: hidden; 
  }

  /* 하단 액션바 */
  .mobile-actionbar{
    position: fixed; left: 0; right: 0; bottom: 0;
    z-index: 1100;
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 8px;
    padding: 8px 12px calc(8px + env(safe-area-inset-bottom));
    background: var(--glass-bg);
    backdrop-filter: blur(6px);
    border-top: 1px solid var(--border);
  }

  .mobile-actionbar button{
    height: 44px;
    padding: 10px 8px;
    border: 0;
    background: transparent;
    border-radius: 10px;
    font-weight: 700;
    color: var(--text);
    box-shadow: none;
  }

  .mobile-actionbar button:disabled{ opacity: .45; }
  .mobile-actionbar button:not(:disabled):hover{ 
    background: var(--glass-hover);    
  }

  .mobile-actionbar button:not(:disabled):active{ 
    background: var(--glass-active);
  }

  .mobile-actionbar button:focus-visible{
    outline: 2px solid var(--focus-ring);       
    outline-offset: 2px;
  }

  .fm-item { 
    position: relative;
    display: grid;
    grid-template-columns: 56px 1fr;
    column-gap: 12px;
    align-items: center;
    padding: 12px;
    border-radius: 12px;
    min-width: 0; /* 내부 말줄임 보조 */
  }

  .fm-thumb { 
    grid-column: 1 / 2; 
    width: 40px; height: 40px; 
    border-radius: 8px; 
    display: grid; place-items: center;
    background: var(--surface-muted); border: 1px solid var(--border);
  }

  .fm-item.kind-folder .fm-thumb::before { content: "📁"; font-size: 20px; }
  .fm-item.kind-file   .fm-thumb::before { content: "📄"; font-size: 20px; }

  /* 텍스트 래퍼가 실제 그리드 아이템 */
  .fm-text{
    grid-column: 2 / 3;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
  }

  .fm-name, .fm-meta { 
    min-width: 0;
    max-width: 100%;
    overflow: hidden; 
    text-overflow: ellipsis; 
    white-space: nowrap;
  }

  .fm-name { font-size: .95rem; font-weight: 700; color: var(--text); line-height: 1.2; }
  .fm-meta { font-size: .9rem;  color: var(--text-muted); }

  .fm-item.is-selected { outline: 2px solid var(--focus-ring); outline-offset: 2px; }

  /* 체크박스 – 기본 숨김, 선택모드에서만 노출 */
  .fm-select {
    display: none;
    position: absolute; left: 8px; top: 8px; 
    width: 18px; height: 18px; z-index: 1;
  }
  .select-mode .fm-select { display: block; }
}

/* 디스크 칩 아이콘 키우기 */
.disk-chip {
		display: inline-flex;
		align-items: center;
		gap: 10px;             
		padding: 6px 12px;
		border: 1px solid var(--border);
		border-radius: 999px;
		background: var(--surface);
		box-shadow: 0 6px 16px -12px rgba(0,0,0,.25);
		font-size: .92rem;
}

/* 아이콘이 pseudo 또는 img로 들어올 때 모두 커지도록 */
.disk-chip .icon,
.disk-chip::before {
		width: 22px; height: 22px;
		flex: 0 0 22px;
		display: inline-block;
		background-size: contain;
		background-position: center;
		background-repeat: no-repeat;
}

.disk-chip .bar {
		width: 110px;           
		height: 8px;
		background: var(--surface-muted);
		border-radius: 999px;
		overflow: hidden;
}

.disk-chip .bar > i {
		display: block;
		height: 100%;
		background-color: var(--nav-bg);
		width: 0%;
}


/* 전체 배경/문자색 통일 */
body { background: var(--bg); color: var(--text); }

/* 버튼 공통 사항 라이트/다크 자동 전환 */
button:not(.menu-icon), .logout-btn, .restricted-menu, .action-btn, .btn{
		background: var(--btn-primary-bg);
		color: var(--btn-text);
		border: 1px solid var(--border);
		border-radius: 8px;
		padding: 10px 16px;
		font-weight: 700;
		cursor: pointer;
		box-shadow: none;
		transition: background-color .2s ease, 
		border-color .2s ease, 
		box-shadow .2s ease;
}

button:not(.menu-icon):hover,
.logout-btn:hover, .restricted-menu:hover, .action-btn:hover, .btn:hover{
		background: var(--btn-primary-hover);
		border-color: var(--border);
}

button:not(.menu-icon):focus-visible,
.logout-btn:focus-visible, .restricted-menu:focus-visible, .action-btn:focus-visible, .btn:focus-visible{
		outline: 2px solid var(--btn-primary-hover);
		outline-offset: 2px;
}

button:disabled{
		opacity: .55;
		cursor: not-allowed;
}

/* 카드/패널 */
.card, .tile, .panel, .table-container, .modal{
		background: var(--card);
		border: 1px solid var(--border);
		border-radius: 12px;
		box-shadow: 0 1px 2px rgba(0,0,0,.03);
		backdrop-filter: none;
}

/* 스크롤바 */
*::-webkit-scrollbar{ width:12px; height:12px; }
*::-webkit-scrollbar-thumb{
		background: var(--accent-strong);
		border-radius: 10px;
		border: 2px solid var(--accent);
}

*{ scrollbar-width: thin; scrollbar-color: var(--accent-strong) var(--accent); }

/* sys-dashboard */
.sys-dashboard{
	margin: 8px 0 20px;
	padding: 14px;
	background: var(--card);
	border: 1px solid var(--border);
	border-radius: 8px;
}
.sys-dashboard-head,
.disk-section-head{
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 12px;
	text-align: left;
}
.sys-dashboard-head{ margin-bottom: 12px; }
.sys-dashboard.is-collapsed .sys-dashboard-head{ margin-bottom: 0; }
.sys-dashboard-body[hidden]{ display: none; }
.sys-dashboard-toggle{
	min-width: 64px;
	padding: 6px 10px;
	border-radius: 6px;
	font-size: 12px;
	font-weight: 700;
}
.sys-dashboard-title{
	display: flex;
	align-items: center;
	gap: 8px;
	font-size: 16px;
	font-weight: 800;
	color: var(--text);
}
.sys-live-dot{
	width: 8px;
	height: 8px;
	border-radius: 50%;
	background: #22c55e;
	box-shadow: 0 0 0 3px rgba(34,197,94,.14);
}
.sys-updated,
.disk-section-head span:last-child{
	font-size: 12px;
	color: var(--text-muted);
}
.sys-updated{ margin: 3px 0 0 16px; }
.disk-section-head{
	margin: 14px 2px 8px;
	font-size: 13px;
	font-weight: 700;
	color: var(--text);
}
.sys-dashboard .row{ display:grid; gap:10px; }
.sys-dashboard .row + .row{ margin-top:10px; }

.sys-dashboard .row-main{ 
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.sys-dashboard .row-disks{ 
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.sys-dashboard .row-disks .tile-brief{
		font-size: clamp(11px, 1.6vw, 13px);
		color: var(--text-muted);
		white-space: nowrap;           
		font-variant-numeric: tabular-nums;
}

.sys-dashboard .row-disks .tile-value{
	  font-size: clamp(14px, 3.6vw, 16px);
}

.sys-dashboard .tile{
	position: relative;
	padding: 11px 12px;
	border-radius: 6px;
	box-shadow: none;
	overflow: hidden;
}
.sys-dashboard .tile::before{
	content: "";
	position: absolute;
	inset: 0 auto 0 0;
	width: 3px;
	background: #6366f1;
}
.sys-dashboard .tile[data-level="warning"]::before{ background: #f59e0b; }
.sys-dashboard .tile[data-level="danger"]::before{ background: #ef4444; }
.sys-dashboard .tile-head{
	display:flex;
	justify-content:space-between;
	align-items:center;
	gap: 10px;
	margin-bottom:5px;
	min-width: 0;
}
.sys-dashboard .tile-title,
.sys-dashboard .tile-sub,

#net-rate {
	 word-break: keep-all;        
}

.sys-dashboard .tile-value{
		font-size: 18px;
		font-weight:800;
		letter-spacing:0;
		margin-bottom:5px;
		font-variant-numeric: tabular-nums;
}

#net-rate {
		font-size: clamp(14px, 4vw, 16px);
		line-height:1.3;
}

.sys-dashboard .tile-sub{
		font-size: 12px;
		color: var(--text-muted);
		white-space: nowrap;
		overflow: hidden;
		text-overflow: ellipsis;
}

.sys-dashboard .progress{
		height:6px;
		background: var(--accent);
		border:0;
		border-radius:999px;
		overflow:hidden;
}
.sys-dashboard .progress-bar{
		height:100%;
		width:0%;
		background: #6366f1;
		transition: width .2s ease;
}
.sys-dashboard .tile[data-level="warning"] .progress-bar{ background: #f59e0b; }
.sys-dashboard .tile[data-level="danger"] .progress-bar{ background: #ef4444; }

.sys-dashboard .tile .tile-sub small{ opacity:.85; }


/* 햄버거 아이콘 애니메이션 제거 */
.menu-icon,
.menu-icon * { transition: none !important; animation: none !important; }
.menu-icon:hover,
.menu-icon:active,
.menu-icon:focus { transform: translateY(-50%) !important; }


/* 메뉴 아이콘: 호버/포커스/액티브 배경/애니메이션 제거 */
.navbar-container .menu-icon,
.navbar-container .menu-icon:hover,
.navbar-container .menu-icon:focus,
.navbar-container .menu-icon:active{
		background: transparent !important;
		border: 0 !important;
		box-shadow: none !important;
		transition: none !important;
		animation: none !important;
}


/* 900px 이하 태블릿 등 가로 환경 보정 */
@media (max-width: 900px) {
  .sys-dashboard .row { gap: 10px; }
  .sys-dashboard .tile { padding: 12px; }
  .sys-dashboard .row-main{ grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }
  .sys-dashboard .row-disks{ grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); }
}

/* 600px 이하 일반적인 스마트폰 세로(포트레이트) */
@media (max-width: 600px) {
  /* 1행은 1열로 자연스럽게, 디스크는 2열까지 */
  .sys-dashboard .row-main{ grid-template-columns: 1fr; }
  .sys-dashboard .row-disks{ grid-template-columns: repeat(2, minmax(0, 1fr)); }

  .sys-dashboard .row { gap: 8px; }
  .sys-dashboard .tile { padding: 10px 12px; }
  .sys-dashboard{ padding: 10px; }
  .sys-dashboard .tile-title{ font-size: clamp(13px, 3.6vw, 15px); }
  .sys-dashboard .tile-sub{   font-size: clamp(12px, 3.2vw, 14px); }
}


