    newExtension = prompt("새로운 파일 확장자를 입력하세요 (.ts, .mp4):", extension);
    if (newExtension === null) return;
  }

  fetch(`/api/channels/${id}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
